import{z as A,x as B,o as t,c as p,q as s,j as i,D as E,d as e,s as n,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"各向异性与侧壁钝化","description":"","frontmatter":{"title":"各向异性与侧壁钝化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/anisotropy-passivation.md","filePath":"litho/anisotropy-passivation.md","lastUpdated":1791063341000}'),d={name:"litho/anisotropy-passivation.md"};function D(h,a,m,u,c,f){const r=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="各向异性与侧壁钝化" tabindex="-1">各向异性与侧壁钝化 <a class="header-anchor" href="#各向异性与侧壁钝化" aria-label="Permalink to &quot;各向异性与侧壁钝化&quot;">​</a></h1><div class="epigraph"><p>各向异性不是离子「只会往下打」的神话；侧壁靠聚合物或氧化层挡住横向化学，底部靠离子把钝化打掉。</p><footer>—— 对照 RIE 钝化–离子协同的教材图像；Coburn–Winters 之后的侧壁化学通称</footer></div><p><a href="/litho/hardmask-sin-tin">上一课</a>把深度交给硬掩模。缺口是剖面：开口要直、底要清、侧壁不能长瘤或挖空。本课钉各向异性与侧壁钝化。负载效应如何让钝化通量随密度变，留给<a href="/litho/etch-loading-effect">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯化学刻蚀各向同性，细线立不住；纯溅射损伤大、选择比差。RIE 的直壁来自：<strong>底部</strong>离子去钝化 + 反应，<strong>侧壁</strong>钝化膜挡横向。含氟碳的介质刻蚀、HBr/O<sub>2</sub> 的多晶硅、金属氯化学，钝化物种不同，逻辑同构。钝化太厚：底清不掉、CD 缩、弓形；太薄：腰斩、底切、选择比崩。</p><p><span class="marginnote">术语翻译：各向异性就是『刻蚀速度随方向不同』——这里指纵向快、横向慢，开口才立得直。反义是各向同性：像糖块在水里溶化，四面八方一样快，细线很快被掏倒。</span></p><p>缺口是<strong>剖面旋钮</strong>，不是再讲鞘层。OPC 紧凑核通常不显式含侧壁角；3D 胶/刻蚀抽检才看见钝化失败。把顶视 CD 当直壁，电学和打穿会反对。</p><h3 id="钝化是图形相关的" tabindex="-1">钝化是图形相关的 <a class="header-anchor" href="#钝化是图形相关的" aria-label="Permalink to &quot;钝化是图形相关的&quot;">​</a></h3><p>聚合物前体来自气体和被刻的胶/硬掩模。开口率高，碳源与消耗变，侧壁膜厚随局部环境走——这就是下一课负载的化学面。孤立线与密线剖面可以一个垂直、一个倾斜，AEI CD 却被调到同一数。</p><p><span class="marginnote">过刻阶段钝化条件往往与主刻不同。主刻直、过刻腰斩，是常见的食谱拼接错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>旋钮：聚合物比（C/F、O<sub>2</sub> 添加）、离子能量、温度、气压（角分布）。计量：截面 TEM/SEM、侧壁角、底脚、弓形、残留。与选择比课联立：同一聚合物既保硬掩模又保侧壁，窗口是三维的。ALE 用循环把钝化与去除拆开，本课承认它是钝化逻辑的极限形式，不展开循环时序。</p><p><span class="marginnote">直觉类比：侧壁钝化像喷漆前贴美纹纸——喷枪（离子）只打得动没贴纸的地面（底部）。纸贴太厚连地面也护住（刻不动、底清不掉），贴太薄墙面被喷坏（侧壁被啃出底切）。</span></p><p>剖面规格要对代表 AR 和开口率，而不是只切一条密线。主刻与过刻的钝化比若分家，应分两段计量，避免「平均侧壁角」掩盖过刻腰斩。</p><p><span class="marginnote">侧壁角的小数字：一个 2 μm 深的孔，侧壁从 90° 偏到 85°，孔底相对孔口横向偏出约 2000 × tan5° ≈ 175 nm——足以吞掉一条 20 nm 级 CD 的全部预算。</span></p>',15)),(t(),i(l,null,{default:E(()=>[n(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20KNOB%5B%22%E6%97%8B%E9%92%AE%3A%20%E8%81%9A%E5%90%88%E7%89%A9%E6%AF%94%20%2F%20%E7%A6%BB%E5%AD%90%E8%83%BD%E9%87%8F%20%2F%20%E6%B8%A9%E5%BA%A6%20%2F%20%E6%B0%94%E5%8E%8B%22%5D%20--%3E%20THK%5B%22%E4%BE%A7%E5%A3%81%E9%92%9D%E5%8C%96%E5%8E%9A%E5%BA%A6%22%5D%0A%20%20LDEN%5B%22%E5%BC%80%E5%8F%A3%E7%8E%87%20%2F%20%E8%B4%9F%E8%BD%BD%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20THK%0A%20%20THK%20--%3E%20GOOD%5B%22%E5%B9%B3%E8%A1%A1%E5%B8%A6%3A%20%E7%9B%B4%E5%A3%81%20%2B%20%E5%BA%95%E6%B8%85%22%5D%0A%20%20THK%20--%3E%20THIN%5B%22%E5%A4%AA%E8%96%84%3A%20%E5%BA%95%E5%88%87%20%2F%20%E8%85%B0%E6%96%A9%20%2F%20%E9%80%89%E6%8B%A9%E6%AF%94%E5%B4%A9%22%5D%0A%20%20THK%20--%3E%20THICK%5B%22%E5%A4%AA%E5%8E%9A%3A%20%E5%BC%93%E5%BD%A2%20%2F%20CD%20%E7%BC%A9%20%2F%20%E5%BA%95%E4%B8%8D%E6%B8%85%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"侧壁膜生长速率对离子通量不敏感（少离子），对中性通量和表面温度敏感。底部膜被离子溅射或离子协助反应去掉。角分布宽时，侧壁也被离子擦到，钝化变薄，出现弓形。电荷在高 AR 孔的累积会弯离子轨迹，侧壁出现缺口——几何 ARDE 的电场版。剖面进入 via 填充和可靠性（虚空、击穿）。",-1)),(t(),i(l,null,{default:E(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20POLY%5B%22%E9%92%9D%E5%8C%96%E5%89%8D%E4%BD%93%22%5D%20--%3E%20SW%5B%22%E4%BE%A7%E5%A3%81%E8%86%9C%22%5D%0A%20%20ION%5B%22%E7%A6%BB%E5%AD%90%22%5D%20--%3E%20BOT%5B%22%E5%8E%BB%E9%92%9D%E5%8C%96%20%2B%20%E5%8F%8D%E5%BA%94%22%5D%0A%20%20SW%20--%3E%20ANI%5B%22%E5%90%84%E5%90%91%E5%BC%82%E6%80%A7%E5%89%96%E9%9D%A2%22%5D%0A%20%20BOT%20--%3E%20ANI%0A%20%20ANG%5B%22%E7%A6%BB%E5%AD%90%E8%A7%92%E5%B0%BE%22%5D%20--%3E%20BOW%5B%22%E5%BC%93%E5%BD%A2%20%2F%20%E5%BA%95%E5%88%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p>离子角尾把侧壁膜擦薄，图中弓形与底切是同一平衡被破坏的两种脸。剖面规格要分主刻与过刻，不能只报平均角。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写某气体的未公开配比。不把钝化当缺陷课的颗粒源展开。光学侧壁角（胶）与刻蚀侧壁角不要混报。</p><p>后课默认：直壁是钝化与离子的平衡，随开口率漂。下一课把这漂移命名为负载，并接到填充与 dummy。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>各向异性 = 侧壁钝化 + 底部离子去钝化，不是离子神话。</li><li>钝化厚度随开口率与过刻阶段变，顶视 CD 不够。</li><li>剖面进入填充与可靠性。</li><li>出处：RIE 钝化协同教材图像；Coburn–Winters 传统。</li></ul>',6))])}const _=A(d,[["render",D]]);export{T as __pageData,_ as default};
